import random

# all class and function definitions in the code file, if any
class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients

    def __mul__(self, other):
        new_coefficients = [0] * (len(self.coefficients) + len(other.coefficients) - 1)
        for i, coef1 in enumerate(self.coefficients):
            for j, coef2 in enumerate(other.coefficients):
                new_coefficients[i + j] += coef1 * coef2
        return Polynomial(new_coefficients)

    def __add__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        new_coefficients = [0] * max_len
        for i in range(max_len):
            if i < len(self.coefficients):
                new_coefficients[i] += self.coefficients[i]
            if i < len(other.coefficients):
                new_coefficients[i] += other.coefficients[i]
        return Polynomial(new_coefficients)

    def __sub__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        new_coefficients = [0] * max_len
        for i in range(max_len):
            if i < len(self.coefficients):
                new_coefficients[i] += self.coefficients[i]
            if i < len(other.coefficients):
                new_coefficients[i] -= other.coefficients[i]
        return Polynomial(new_coefficients)

    def __str__(self):
        return " + ".join(f"{coef}x^{i}" for i, coef in enumerate(self.coefficients) if coef != 0)

class RationalExpression:
    def __init__(self, numerator, denominator):
        self.numerator = numerator
        self.denominator = denominator

    def __mul__(self, other):
        return RationalExpression(self.numerator * other.numerator, self.denominator * other.denominator)

    def __add__(self, other):
        common_denominator = self.denominator * other.denominator
        new_numerator = (self.numerator * other.denominator) + (other.numerator * self.denominator)
        return RationalExpression(new_numerator, common_denominator)

    def __sub__(self, other):
        common_denominator = self.denominator * other.denominator
        new_numerator = (self.numerator * other.denominator) - (other.numerator * self.denominator)
        return RationalExpression(new_numerator, common_denominator)

    def __str__(self):
        return f"({self.numerator}) / ({self.denominator})"

# main function
